mapper.select:
SELECT pc.Pc_Code, pc.Pc_Seq, pc.Pc_Date, pc.Pc_Flag, pc.Pc_JumFg, pc.Pc_Area1, Pc_Area1Nm = ar1.Ar_Name, pc.Pc_Area2, Pc_Area2Nm = ar2.Ar_Name, pc.Pc_RepairPrCD, Pc_RepairPrNm = pr.Pr_Name, pc.Pc_RepairItem, pc.Pc_RepairAmt, pc.Pc_Remark, pc.Pc_RegDate, pc.Pc_UserID, Pc_UserNm = dbo.GetSaNm(pc.Pc_UserID) FROM I_PropertyChange pc LEFT JOIN I_Area ar1 ON ar1.Ar_Code = pc.Pc_Area1 LEFT JOIN I_Area ar2 ON ar2.Ar_Code = pc.Pc_Area2 LEFT JOIN J_ProVider pr ON CONVERT(VARCHAR(50), pr.Pr_Code) = CONVERT(VARCHAR(50), pc.Pc_RepairPrCD) AND ISNULL(pr.Pr_Name, '') <> '' WHERE pc.Pc_Flag = #{pcFlag} AND pc.Pc_Code = #{ppCode}
ORDER BY pc.Pc_Date
ORDER BY pc.Pc_Date, pc.Pc_Seq
